To solve this problem, we need to count the number of ways to color the edges of a complete graph with \( n \) vertices such that:
1. There is at least one red edge.
2. There is at least one blue edge.
3. For any set of vertices \( S \) with \( |S| \geq 2 \), \( S \) is either red-connected or blue-connected, but not both.

This problem can be approached using dynamic programming. We'll define a state \( dp[i][j] \) where \( i \) is the number of vertices and \( j \) is a bitmask representing the coloring of the edges incident to the first \( i \) vertices.

Here's the Python code to solve the problem:

```python
MOD = 998244353

def count_ways(n):
    if n == 3:
        return 6

    # Initialize dp array
    dp = [[0] * (1 << (n - 1)) for _ in range(n + 1)]
    dp[3][0b10] = 1
    dp[3][0b01] = 1

    for i in range(4, n + 1):
        for mask in range(1 << (i - 1)):
            for submask in range(mask):
                if (mask & submask) == 0 and is_connected(i, mask, submask):
                    dp[i][mask] += dp[i - 1][submask]
                    dp[i][mask] %= MOD

    result = 0
    for mask in range(1 << (n - 1)):
        result += dp[n][mask]
        result %= MOD

    return result

def is_connected(n, mask, submask):
    edges = []
    for i in range(n - 1):
        if (mask & (1 << i)) and (submask & (1 << i)):
            edges.append((i, i + 1))
        elif (mask & (1 << i)) or (submask & (1 << i)):
            edges.append((0, i + 1))

    # Check if the graph is connected
    visited = [False] * n
    stack = [0]
    while stack:
        node = stack.pop()
        if not visited[node]:
            visited[node] = True
            for neighbor in range(n):
                if (node, neighbor) in edges or (neighbor, node) in edges:
                    stack.append(neighbor)

    return all(visited)

# Read input
n = int(input().strip())
print(count_ways(n))
